function answerFrame(ws: WebSocket, session: ChatSession, sessionStore: SessionStore, validation: ValidationResult) {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') answerListSessions(ws, session, sessionStore, message);
}

// Answered beside ping, never under the lock: a history request is not a turn and must not queue behind a streaming answer.
function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore,
  message: ListSessionsMessage
): void {
  if (!sessionStore.listFor) {
    sendList(ws, []);
    return;
  }

  let listed: Awaitable<SessionSummary[]>;
  try {
    // The user is the connection's, read off the upgrade: a frame naming another user's id changes nothing.
    listed = sessionStore.listFor((ws as ExtWebSocket).userId, {limit: message.limit, before: message.before});
  } catch (error) {
    listFailed(ws, session, error);
    return;
  }

  // A store may answer directly or resolve to: only the resolving one is waited for, so a synchronous
  // list is on the wire before the next frame is read.
  if (!(listed instanceof Promise)) {
    sendList(ws, listed);
    return;
  }
  void listed.then(
    summaries => sendList(ws, summaries),
    (error: unknown) => listFailed(ws, session, error)
  );
}

// Dates do not survive JSON.stringify: the wire carries the two times as ISO strings, and the row nothing else.
function sendList(ws: WebSocket, summaries: SessionSummary[]): void {
  const sessions: SessionListMessage['sessions'] = summaries.map(summary => ({
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  }));
  sendJson(ws, {type: 'session_list', sessions});
}

// The frame carries no store detail: a client that cannot list renders a failure, not a database message.
function listFailed(ws: WebSocket, session: ChatSession, error: unknown): void {
  log.error('ws', 'listing conversations failed', {
    sessionId: session.sessionId,
    userId: (ws as ExtWebSocket).userId,
    error: messageOf(error),
  });
  sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
}

